//! The built graph, which may contain cycles, and validation into a [`Dag`].

use alloc::sync::Arc;
use alloc::vec;
use alloc::vec::Vec;
use core::borrow::Borrow;

use crate::algo::{cyclic_components, kahn, shortest_cycle, Csr};
use crate::builder::lookup;
use crate::dag::Dag;
use crate::violation::{Cycle, Violation, Violations};
use crate::{NodeIx, Order, UnknownTargets};

#[derive(Debug, Clone)]
pub(crate) struct Edge<E> {
    pub(crate) dependent: u32,
    pub(crate) prerequisite: u32,
    pub(crate) kind: E,
    pub(crate) seq: usize,
}

/// An edge whose prerequisite no node has. Kept whatever the [`UnknownTargets`] policy.
#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Dangling<K, E = ()> {
    /// The node declaring the edge.
    pub dependent: NodeIx,
    /// The key no node has.
    pub prerequisite: K,
    /// The edge's kind.
    pub kind: E,
    pub(crate) seq: usize,
}

/// One edge as an edge filter sees it.
#[non_exhaustive]
#[derive(Debug)]
pub struct EdgeRef<'a, K, E> {
    /// The node that depends on `prerequisite`.
    pub dependent: &'a K,
    /// The node that comes first.
    pub prerequisite: &'a K,
    /// The edge's kind.
    pub kind: &'a E,
    /// `dependent`'s index.
    pub dependent_ix: NodeIx,
    /// `prerequisite`'s index.
    pub prerequisite_ix: NodeIx,
}

impl<K, E> Clone for EdgeRef<'_, K, E> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<K, E> Copy for EdgeRef<'_, K, E> {}

/// A built graph. It may contain cycles; [`Graph::validate`] proves it does not and returns a [`Dag`].
#[derive(Debug, Clone)]
pub struct Graph<K, E = ()> {
    pub(crate) keys: Arc<[K]>,
    pub(crate) by_key: Arc<[u32]>,
    pub(crate) edges: Vec<Edge<E>>,
    pub(crate) dangling: Vec<Dangling<K, E>>,
    pub(crate) duplicates: Vec<K>,
    pub(crate) unknown: UnknownTargets,
    pub(crate) overflow: bool,
}

/// The adjacency of the edges a filter kept, without self-loops.
pub(crate) struct Kept {
    pub(crate) prerequisites: Csr,
    pub(crate) dependents: Csr,
    self_loop: Vec<bool>,
    /// The declaration sequence of each node's first kept self-edge.
    self_loop_seq: Vec<Option<usize>>,
    pub(crate) rank: Vec<u32>,
    pub(crate) by_rank: Vec<u32>,
}

impl<K: Ord + Clone, E: Ord> Graph<K, E> {
    /// Number of nodes, not counting duplicate declarations.
    #[must_use]
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Whether the graph has no nodes.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    /// The key of node `ix`.
    #[must_use]
    pub fn key(&self, ix: NodeIx) -> Option<&K> {
        self.keys.get(ix.u())
    }

    /// The node with `key`.
    pub fn index_of<Q>(&self, key: &Q) -> Option<NodeIx>
    where
        K: Borrow<Q>,
        Q: Ord + ?Sized,
    {
        lookup(&self.keys, &self.by_key, key).map(NodeIx)
    }

    /// Edges whose prerequisite no node has, in declaration order.
    #[must_use]
    pub fn dangling(&self) -> &[Dangling<K, E>] {
        &self.dangling
    }

    /// Keys declared more than once, one entry per later declaration, in declaration order.
    #[must_use]
    pub fn duplicates(&self) -> &[K] {
        &self.duplicates
    }

    /// Validates the graph with every edge. See [`Graph::validate_filtered`].
    ///
    /// # Errors
    ///
    /// [`Violations`] listing every problem when the graph is not a valid dag.
    pub fn validate(&self, order: Order) -> Result<Dag<K>, Violations<K>> {
        self.validate_filtered(|_| true, order)
    }

    /// Validates the graph with the edges `keep` accepts and returns a [`Dag`], or every problem at once, in this
    /// order: duplicate nodes, then unknown dependencies (unless ignored) and self-dependencies by the dependent's
    /// declaration position and the edge's, then cycles. Cycles made only of rejected edges are not problems.
    ///
    /// # Errors
    ///
    /// [`Violations`] listing every problem when the kept edges do not form a valid dag.
    pub fn validate_filtered(
        &self,
        keep: impl FnMut(EdgeRef<'_, K, E>) -> bool,
        order: Order,
    ) -> Result<Dag<K>, Violations<K>> {
        let kept = self.kept(keep, order);
        let n = self.len();
        let mut violations: Vec<Violation<K>> =
            self.duplicates.iter().map(|key| Violation::DuplicateNode { key: key.clone() }).collect();
        if self.overflow {
            violations.push(Violation::TooManyNodes);
        }

        // Unknown dependencies and self-dependencies, by dependent then edge declaration order.
        let mut edge_problems: Vec<(u32, usize, Violation<K>)> = Vec::new();
        if self.unknown == UnknownTargets::Error {
            for d in &self.dangling {
                if let Some(dependent) = self.key(d.dependent) {
                    edge_problems.push((
                        d.dependent.0,
                        d.seq,
                        Violation::UnknownDependency {
                            dependent: dependent.clone(),
                            prerequisite: d.prerequisite.clone(),
                        },
                    ));
                }
            }
        }
        for (i, seq) in kept.self_loop_seq.iter().enumerate() {
            if let (Some(seq), Some(key), Ok(i)) = (seq, self.keys.get(i), u32::try_from(i)) {
                edge_problems.push((i, *seq, Violation::SelfDependency { key: key.clone() }));
            }
        }
        edge_problems.sort_by_key(|&(d, seq, _)| (d, seq));
        violations.extend(edge_problems.into_iter().map(|(_, _, v)| v));

        let topo = kahn(n, &kept.prerequisites, &kept.dependents, &kept.rank, &kept.by_rank);
        if topo.len() < n {
            let mut left = vec![true; n];
            for ix in &topo {
                if let Some(l) = left.get_mut(ix.u()) {
                    *l = false;
                }
            }
            let no_self = vec![false; n];
            for cycle in self.cycles_in(&left, &kept, &no_self) {
                violations.push(Violation::Cycle(cycle));
            }
        }

        if !violations.is_empty() {
            return Err(Violations::new(violations));
        }
        Ok(Dag::new(Arc::clone(&self.keys), Arc::clone(&self.by_key), kept, topo))
    }

    /// The cycles among the edges `keep` accepts, for graphs that may legitimately contain them. Each strongly
    /// connected component that forms a cycle is reported once, a node with an edge to itself included.
    #[must_use]
    pub fn cycles(&self, keep: impl FnMut(EdgeRef<'_, K, E>) -> bool, order: Order) -> Vec<Cycle<K>> {
        let kept = self.kept(keep, order);
        let all = vec![true; self.len()];
        self.cycles_in(&all, &kept, &kept.self_loop)
    }

    fn cycles_in(&self, members: &[bool], kept: &Kept, self_loop: &[bool]) -> Vec<Cycle<K>> {
        let rank = |ix: &NodeIx| kept.rank.get(ix.u()).copied().unwrap_or(u32::MAX);
        let mut components = cyclic_components(members, &kept.prerequisites, &kept.dependents, self_loop);
        for c in &mut components {
            c.sort_unstable_by_key(rank);
        }
        components.sort_unstable_by_key(|c| c.first().map_or(u32::MAX, rank));
        let mut inside = vec![false; self.len()];
        components
            .into_iter()
            .map(|component| {
                for ix in &component {
                    if let Some(f) = inside.get_mut(ix.u()) {
                        *f = true;
                    }
                }
                let path = match component.first() {
                    Some(&start) if component.len() > 1 => shortest_cycle(start, &inside, &kept.prerequisites),
                    Some(&start) => vec![start],
                    None => Vec::new(),
                };
                for ix in &component {
                    if let Some(f) = inside.get_mut(ix.u()) {
                        *f = false;
                    }
                }
                let keys = |ixs: &[NodeIx]| ixs.iter().filter_map(|ix| self.key(*ix).cloned()).collect();
                Cycle::new(keys(&component), keys(&path))
            })
            .collect()
    }

    fn edge_ref<'a>(&'a self, e: &'a Edge<E>) -> Option<EdgeRef<'a, K, E>> {
        Some(EdgeRef {
            dependent: self.keys.get(e.dependent as usize)?,
            prerequisite: self.keys.get(e.prerequisite as usize)?,
            kind: &e.kind,
            dependent_ix: NodeIx(e.dependent),
            prerequisite_ix: NodeIx(e.prerequisite),
        })
    }

    fn kept(&self, mut keep: impl FnMut(EdgeRef<'_, K, E>) -> bool, order: Order) -> Kept {
        let n = self.len();
        let rank: Vec<u32> = match order {
            Order::Declaration => (0..n).filter_map(|i| u32::try_from(i).ok()).collect(),
            Order::Key => {
                let mut rank = vec![0u32; n];
                for (r, &i) in self.by_key.iter().enumerate() {
                    if let (Some(slot), Ok(r)) = (rank.get_mut(i as usize), u32::try_from(r)) {
                        *slot = r;
                    }
                }
                rank
            }
        };
        let mut by_rank = vec![0u32; n];
        for (i, &r) in rank.iter().enumerate() {
            if let (Some(slot), Ok(i)) = (by_rank.get_mut(r as usize), u32::try_from(i)) {
                *slot = i;
            }
        }
        let mut self_loop = vec![false; n];
        let mut self_loop_seq: Vec<Option<usize>> = vec![None; n];
        let mut forward = Vec::with_capacity(self.edges.len());
        for e in &self.edges {
            let Some(edge) = self.edge_ref(e) else { continue };
            if !keep(edge) {
                continue;
            }
            if e.dependent == e.prerequisite {
                if let Some(s) = self_loop.get_mut(e.dependent as usize) {
                    *s = true;
                }
                if let Some(s @ None) = self_loop_seq.get_mut(e.dependent as usize) {
                    *s = Some(e.seq);
                }
            } else {
                forward.push((e.dependent, e.prerequisite));
            }
        }
        let backward = forward.iter().map(|&(d, p)| (p, d)).collect();
        Kept {
            prerequisites: Csr::from_pairs(n, forward, &rank),
            dependents: Csr::from_pairs(n, backward, &rank),
            self_loop,
            self_loop_seq,
            rank,
            by_rank,
        }
    }
}

//! Declaring nodes and edges.

use alloc::sync::Arc;
use alloc::vec::Vec;

use crate::graph::{Dangling, Edge, Graph};
use crate::{NodeIx, UnknownTargets};

/// A node declaration, returned by [`GraphBuilder::node`]. Edges hang off the declaration rather than the key, so the
/// edges of a duplicate declaration are dropped with it instead of landing on the first node with that key.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Decl(u32);

/// Collects nodes and edges. [`GraphBuilder::build`] never fails; problems are reported when the graph is validated.
#[derive(Debug, Clone)]
pub struct GraphBuilder<K, E = ()> {
    decls: Vec<K>,
    edges: Vec<(u32, K, E)>,
    overflow: bool,
}

impl<K: Ord + Clone, E: Ord> Default for GraphBuilder<K, E> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K: Ord + Clone, E: Ord> GraphBuilder<K, E> {
    /// An empty builder.
    #[must_use]
    pub fn new() -> Self {
        Self { decls: Vec::new(), edges: Vec::new(), overflow: false }
    }

    /// An empty builder with room for `nodes` declarations.
    #[must_use]
    pub fn with_capacity(nodes: usize) -> Self {
        Self { decls: Vec::with_capacity(nodes), edges: Vec::with_capacity(nodes), overflow: false }
    }

    /// Declares a node. A later declaration reusing a key is reported as [`crate::Violation::DuplicateNode`], and the
    /// edges added to it are dropped.
    pub fn node(&mut self, key: K) -> Decl {
        match u32::try_from(self.decls.len()) {
            Ok(n) if n < u32::MAX => {
                self.decls.push(key);
                Decl(n)
            }
            _ => {
                self.overflow = true;
                Decl(u32::MAX)
            }
        }
    }

    /// Adds an edge: `dependent` depends on the node keyed `prerequisite`, which may be declared before or after it.
    /// Repeating an edge with the same kind has no further effect.
    pub fn depends_on(&mut self, dependent: Decl, prerequisite: K, kind: E) -> &mut Self {
        if (dependent.0 as usize) < self.decls.len() {
            self.edges.push((dependent.0, prerequisite, kind));
        }
        self
    }

    /// Builds the graph, keeping every node and edge it can use and recording the rest: duplicate declarations,
    /// edges to unknown keys (always kept in [`Graph::dangling`]; `unknown` decides whether validation reports them)
    /// and more than `u32::MAX - 1` nodes.
    #[must_use]
    pub fn build(self, unknown: UnknownTargets) -> Graph<K, E> {
        let Self { decls, edges, overflow } = self;

        // Declarations sorted by key, ties by position: the first of each run of equal keys is the node.
        let mut sorted: Vec<u32> = (0..decls.len()).filter_map(|i| u32::try_from(i).ok()).collect();
        sorted.sort_by(|&a, &b| decl(&decls, a).cmp(&decl(&decls, b)).then(a.cmp(&b)));
        let mut is_duplicate = alloc::vec![false; decls.len()];
        for pair in sorted.windows(2) {
            if let [a, b] = *pair {
                if decl(&decls, a) == decl(&decls, b) {
                    if let Some(d) = is_duplicate.get_mut(b as usize) {
                        *d = true;
                    }
                }
            }
        }

        let mut node_of_decl: Vec<Option<u32>> = Vec::with_capacity(decls.len());
        let mut keys: Vec<K> = Vec::with_capacity(decls.len());
        let mut duplicates: Vec<K> = Vec::new();
        for (key, dup) in decls.into_iter().zip(is_duplicate) {
            if dup {
                node_of_decl.push(None);
                duplicates.push(key);
            } else {
                node_of_decl.push(u32::try_from(keys.len()).ok());
                keys.push(key);
            }
        }
        let mut by_key: Vec<u32> = (0..keys.len()).filter_map(|i| u32::try_from(i).ok()).collect();
        by_key.sort_by(|&a, &b| decl(&keys, a).cmp(&decl(&keys, b)));

        let mut resolved: Vec<Edge<E>> = Vec::with_capacity(edges.len());
        let mut dangling: Vec<Dangling<K, E>> = Vec::new();
        for (seq, (d, prerequisite, kind)) in edges.into_iter().enumerate() {
            let Some(dependent) = node_of_decl.get(d as usize).copied().flatten() else { continue };
            match lookup(&keys, &by_key, &prerequisite) {
                Some(p) => resolved.push(Edge { dependent, prerequisite: p, kind, seq }),
                None => dangling.push(Dangling { dependent: NodeIx(dependent), prerequisite, kind, seq }),
            }
        }
        // One edge per (dependent, prerequisite, kind), the first declared; then back to declaration order.
        resolved.sort_by(|a, b| {
            (a.dependent, a.prerequisite, &a.kind, a.seq).cmp(&(b.dependent, b.prerequisite, &b.kind, b.seq))
        });
        resolved.dedup_by(|b, a| a.dependent == b.dependent && a.prerequisite == b.prerequisite && a.kind == b.kind);
        resolved.sort_by_key(|e| e.seq);
        dangling.sort_by(|a, b| {
            (a.dependent, &a.prerequisite, &a.kind, a.seq).cmp(&(b.dependent, &b.prerequisite, &b.kind, b.seq))
        });
        dangling.dedup_by(|b, a| a.dependent == b.dependent && a.prerequisite == b.prerequisite && a.kind == b.kind);
        dangling.sort_by_key(|e| e.seq);

        Graph {
            keys: Arc::from(keys),
            by_key: Arc::from(by_key),
            edges: resolved,
            dangling,
            duplicates,
            unknown,
            overflow,
        }
    }
}

fn decl<K>(keys: &[K], i: u32) -> Option<&K> {
    keys.get(i as usize)
}

/// Binary search of `by_key` (node indices sorted by key) for `key`.
pub(crate) fn lookup<K, Q>(keys: &[K], by_key: &[u32], key: &Q) -> Option<u32>
where
    K: core::borrow::Borrow<Q>,
    Q: Ord + ?Sized,
{
    let pos = by_key
        .binary_search_by(|&i| match keys.get(i as usize) {
            Some(k) => k.borrow().cmp(key),
            None => core::cmp::Ordering::Less,
        })
        .ok()?;
    by_key.get(pos).copied()
}

//! What validation reports.

use alloc::vec::Vec;
use core::fmt;

/// Steps of a cycle path printed before the rest is summarized.
const PATH_LIMIT: usize = 8;

/// One strongly connected component that forms a cycle.
#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cycle<K> {
    members: Vec<K>,
    path: Vec<K>,
}

impl<K> Cycle<K> {
    pub(crate) fn new(members: Vec<K>, path: Vec<K>) -> Self {
        Self { members, path }
    }

    /// Every node of the component, in the validation's [`crate::Order`].
    #[must_use]
    pub fn members(&self) -> &[K] {
        &self.members
    }

    /// One shortest loop through the first member: each node depends on the next, and the last depends on the first.
    #[must_use]
    pub fn path(&self) -> &[K] {
        &self.path
    }

    fn write(
        &self,
        f: &mut fmt::Formatter<'_>,
        key: &dyn Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
    ) -> fmt::Result {
        let Some(first) = self.path.first() else { return f.write_str("dependency cycle") };
        f.write_str("dependency cycle: ")?;
        key(first, f)?;
        for (i, k) in self.path.iter().skip(1).enumerate() {
            if i == PATH_LIMIT {
                return write!(f, " … and {} more", self.path.len() - 1 - PATH_LIMIT);
            }
            f.write_str(if i == 0 { " depends on " } else { ", which depends on " })?;
            key(k, f)?;
        }
        f.write_str(if self.path.len() == 1 { " depends on " } else { ", which depends on " })?;
        key(first, f)
    }
}

/// One problem found by validation.
#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Violation<K> {
    /// A later declaration reuses an earlier node's key. Its edges were dropped.
    DuplicateNode {
        /// The repeated key.
        key: K,
    },
    /// A node depends on a key no node has.
    UnknownDependency {
        /// The node declaring the dependency.
        dependent: K,
        /// The missing key.
        prerequisite: K,
    },
    /// A node depends on itself. Reported once per node, never as a cycle.
    SelfDependency {
        /// The node.
        key: K,
    },
    /// Nodes that depend on each other in a loop.
    Cycle(Cycle<K>),
    /// More than `u32::MAX - 1` nodes were declared; the rest were dropped.
    TooManyNodes,
}

impl<K> Violation<K> {
    fn write(
        &self,
        f: &mut fmt::Formatter<'_>,
        key: &dyn Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
    ) -> fmt::Result {
        match self {
            Self::DuplicateNode { key: k } => {
                f.write_str("duplicate node ")?;
                key(k, f)
            }
            Self::UnknownDependency { dependent, prerequisite } => {
                key(dependent, f)?;
                f.write_str(" depends on unknown node ")?;
                key(prerequisite, f)
            }
            Self::SelfDependency { key: k } => {
                key(k, f)?;
                f.write_str(" depends on itself")
            }
            Self::Cycle(cycle) => cycle.write(f, key),
            Self::TooManyNodes => write!(f, "more than {} nodes", u32::MAX - 1),
        }
    }
}

impl<K: fmt::Display> fmt::Display for Violation<K> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.write(f, &|k, f| k.fmt(f))
    }
}

impl<K: fmt::Display> fmt::Display for Cycle<K> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.write(f, &|k, f| k.fmt(f))
    }
}

/// Every problem validation found, in a fixed order: duplicates, then edge problems by the dependent's declaration
/// position and the edge's, then cycles in the validation's [`crate::Order`]. Never empty.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Violations<K> {
    list: Vec<Violation<K>>,
}

impl<K> Violations<K> {
    pub(crate) fn new(list: Vec<Violation<K>>) -> Self {
        Self { list }
    }

    /// The violations.
    #[must_use]
    pub fn as_slice(&self) -> &[Violation<K>] {
        &self.list
    }

    /// The violations, owned.
    #[must_use]
    pub fn into_vec(self) -> Vec<Violation<K>> {
        self.list
    }

    /// Iterates the violations.
    pub fn iter(&self) -> core::slice::Iter<'_, Violation<K>> {
        self.list.iter()
    }

    /// Renders with `key` writing each key, for key types without `Display`.
    pub fn display_with<F>(&self, key: F) -> impl fmt::Display + '_
    where
        F: Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result + 'static,
    {
        DisplayWith { violations: self, key }
    }

    fn write(
        &self,
        f: &mut fmt::Formatter<'_>,
        key: &dyn Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
    ) -> fmt::Result {
        for (i, v) in self.list.iter().enumerate() {
            if i > 0 {
                f.write_str("; ")?;
            }
            v.write(f, key)?;
        }
        Ok(())
    }
}

impl<'a, K> IntoIterator for &'a Violations<K> {
    type Item = &'a Violation<K>;
    type IntoIter = core::slice::Iter<'a, Violation<K>>;
    fn into_iter(self) -> Self::IntoIter {
        self.list.iter()
    }
}

impl<K> IntoIterator for Violations<K> {
    type Item = Violation<K>;
    type IntoIter = alloc::vec::IntoIter<Violation<K>>;
    fn into_iter(self) -> Self::IntoIter {
        self.list.into_iter()
    }
}

impl<K: fmt::Display> fmt::Display for Violations<K> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.write(f, &|k, f| k.fmt(f))
    }
}

impl<K: fmt::Debug + fmt::Display> core::error::Error for Violations<K> {}

struct DisplayWith<'a, K, F> {
    violations: &'a Violations<K>,
    key: F,
}

impl<K, F> fmt::Display for DisplayWith<'_, K, F>
where
    F: Fn(&K, &mut fmt::Formatter<'_>) -> fmt::Result,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.violations.write(f, &self.key)
    }
}

//! A validated, acyclic graph and its queries.

use alloc::sync::Arc;
use alloc::vec;
use alloc::vec::Vec;
use core::borrow::Borrow;

use crate::algo::Csr;
use crate::builder::lookup;
use crate::graph::Kept;
use crate::violation::Violations;
use crate::{GraphBuilder, NodeIx, Order, UnknownTargets};

/// A graph proven to have no cycles, with the edges validation kept. Immutable; cheap to clone.
#[derive(Debug, Clone)]
pub struct Dag<K> {
    keys: Arc<[K]>,
    by_key: Arc<[u32]>,
    prerequisites: Arc<Csr>,
    dependents: Arc<Csr>,
    order: Arc<[NodeIx]>,
    rank: Arc<[u32]>,
    by_rank: Arc<[u32]>,
}

/// The layers of a [`Dag`]: layer 0 holds nodes without prerequisites, and a node's layer is one more than its deepest
/// prerequisite's. Nodes in one layer do not depend on each other.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Layers {
    nodes: Vec<NodeIx>,
    bounds: Vec<usize>,
}

impl Layers {
    /// Number of layers.
    #[must_use]
    pub fn len(&self) -> usize {
        self.bounds.len().saturating_sub(1)
    }

    /// Whether there are no layers (the dag is empty).
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Layer `i`, in the dag's [`Order`].
    #[must_use]
    pub fn get(&self, i: usize) -> Option<&[NodeIx]> {
        let (&start, &end) = (self.bounds.get(i)?, self.bounds.get(i + 1)?);
        self.nodes.get(start..end)
    }

    /// Iterates the layers, first to last.
    pub fn iter(&self) -> impl Iterator<Item = &[NodeIx]> + '_ {
        (0..self.len()).filter_map(|i| self.get(i))
    }
}

impl<K: Ord + Clone> Dag<K> {
    pub(crate) fn new(keys: Arc<[K]>, by_key: Arc<[u32]>, kept: Kept, order: Vec<NodeIx>) -> Self {
        Self {
            keys,
            by_key,
            prerequisites: Arc::new(kept.prerequisites),
            dependents: Arc::new(kept.dependents),
            order: Arc::from(order),
            rank: Arc::from(kept.rank),
            by_rank: Arc::from(kept.by_rank),
        }
    }

    /// Builds and validates in one call, for graphs without edge kinds where an unknown dependency is an error.
    ///
    /// # Errors
    ///
    /// [`Violations`] listing every problem when the nodes do not form a valid dag.
    pub fn from_nodes<I, D>(nodes: I, order: Order) -> Result<Self, Violations<K>>
    where
        I: IntoIterator<Item = (K, D)>,
        D: IntoIterator<Item = K>,
    {
        let nodes = nodes.into_iter();
        let mut b = GraphBuilder::<K>::with_capacity(nodes.size_hint().0);
        for (key, prerequisites) in nodes {
            let node = b.node(key);
            for p in prerequisites {
                b.depends_on(node, p, ());
            }
        }
        b.build(UnknownTargets::Error).validate(order)
    }

    /// Number of nodes.
    #[must_use]
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Whether the dag has no nodes.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    /// The key of node `ix`.
    #[must_use]
    pub fn key(&self, ix: NodeIx) -> Option<&K> {
        self.keys.get(ix.u())
    }

    /// The node at declaration position `position`, for callers that keep per-node data in declaration order. Valid
    /// only for a dag whose graph had no duplicate declarations, which validation guarantees.
    #[must_use]
    pub fn node_at(&self, position: usize) -> Option<NodeIx> {
        if position < self.len() {
            u32::try_from(position).ok().map(NodeIx)
        } else {
            None
        }
    }

    /// The node with `key`.
    pub fn index_of<Q>(&self, key: &Q) -> Option<NodeIx>
    where
        K: Borrow<Q>,
        Q: Ord + ?Sized,
    {
        lookup(&self.keys, &self.by_key, key).map(NodeIx)
    }

    /// The nodes in topological order: the lexicographically smallest valid order under the dag's [`Order`].
    #[must_use]
    pub fn order(&self) -> &[NodeIx] {
        &self.order
    }

    /// The keys in topological order.
    pub fn keys_in_order(&self) -> impl Iterator<Item = &K> + '_ {
        self.order.iter().filter_map(|&ix| self.key(ix))
    }

    /// The nodes `ix` depends on, in the dag's [`Order`]. Empty for an index the dag does not have.
    #[must_use]
    pub fn prerequisites(&self, ix: NodeIx) -> &[NodeIx] {
        self.prerequisites.of(ix.u())
    }

    /// The nodes that depend on `ix`, in the dag's [`Order`]. Empty for an index the dag does not have.
    #[must_use]
    pub fn dependents(&self, ix: NodeIx) -> &[NodeIx] {
        self.dependents.of(ix.u())
    }

    /// The dag's layers. See [`Layers`].
    #[must_use]
    pub fn layers(&self) -> Layers {
        let n = self.len();
        let mut depth = vec![0usize; n];
        for &ix in self.order.iter() {
            let d = self.prerequisites(ix).iter().filter_map(|p| depth.get(p.u())).max().map_or(0, |d| d + 1);
            if let Some(slot) = depth.get_mut(ix.u()) {
                *slot = d;
            }
        }
        let layers = depth.iter().max().map_or(0, |d| d + 1);
        let mut bounds = vec![0usize; layers + 1];
        for &d in &depth {
            if let Some(b) = bounds.get_mut(d + 1) {
                *b += 1;
            }
        }
        for i in 1..bounds.len() {
            let prev = bounds.get(i - 1).copied().unwrap_or(0);
            if let Some(b) = bounds.get_mut(i) {
                *b += prev;
            }
        }
        let mut cursor = bounds.clone();
        let mut nodes = vec![NodeIx(0); n];
        for &i in self.by_rank.iter() {
            let Some(&d) = depth.get(i as usize) else { continue };
            if let Some(c) = cursor.get_mut(d) {
                if let Some(slot) = nodes.get_mut(*c) {
                    *slot = NodeIx(i);
                }
                *c += 1;
            }
        }
        Layers { nodes, bounds }
    }

    /// The nodes that can start now: those for which `eligible(key)` holds and `satisfied(key)` holds for every
    /// prerequisite, in the dag's [`Order`]. One pass over the graph.
    ///
    /// When `satisfied` holds only for nodes that succeeded, a node behind a failure never becomes ready, so direct
    /// prerequisites are enough.
    pub fn ready<'a, S, R>(&'a self, satisfied: S, eligible: R) -> impl Iterator<Item = NodeIx> + 'a
    where
        S: Fn(&K) -> bool + 'a,
        R: Fn(&K) -> bool + 'a,
    {
        self.by_rank.iter().map(|&i| NodeIx(i)).filter(move |&ix| {
            self.key(ix).is_some_and(&eligible)
                && self.prerequisites(ix).iter().all(|&p| self.key(p).is_some_and(&satisfied))
        })
    }

    /// Every node upstream of `roots`, not including the roots, in the dag's [`Order`].
    #[must_use]
    pub fn ancestors(&self, roots: &[NodeIx]) -> Vec<NodeIx> {
        self.closure(roots, &self.prerequisites)
    }

    /// Every node downstream of `roots`, not including the roots, in the dag's [`Order`].
    #[must_use]
    pub fn descendants(&self, roots: &[NodeIx]) -> Vec<NodeIx> {
        self.closure(roots, &self.dependents)
    }

    fn closure(&self, roots: &[NodeIx], next: &Csr) -> Vec<NodeIx> {
        let n = self.len();
        let mut seen = vec![false; n];
        let mut stack: Vec<NodeIx> = Vec::new();
        for r in roots {
            if let Some(s) = seen.get_mut(r.u()) {
                *s = true;
                stack.push(*r);
            }
        }
        let mut found = Vec::new();
        while let Some(ix) = stack.pop() {
            for &m in next.of(ix.u()) {
                if let Some(s) = seen.get_mut(m.u()) {
                    if !*s {
                        *s = true;
                        found.push(m);
                        stack.push(m);
                    }
                }
            }
        }
        found.sort_unstable_by_key(|ix| self.rank.get(ix.u()).copied().unwrap_or(u32::MAX));
        found
    }

    /// Each node's key with its prerequisites' keys, nodes and prerequisites sorted by key, isolated nodes included:
    /// a canonical form of the structure for callers that hash it with their own hasher.
    pub fn canonical(&self) -> impl Iterator<Item = (&K, Vec<&K>)> + '_ {
        self.by_key.iter().filter_map(move |&i| {
            let key = self.keys.get(i as usize)?;
            let mut prerequisites: Vec<&K> =
                self.prerequisites.of(i as usize).iter().filter_map(|&p| self.key(p)).collect();
            prerequisites.sort_unstable();
            Some((key, prerequisites))
        })
    }
}

//! Index-level algorithms: adjacency, Kahn, Kosaraju and shortest cycles. Nothing here recurses.

use alloc::collections::BinaryHeap;
use alloc::vec;
use alloc::vec::Vec;
use core::cmp::Reverse;

use crate::NodeIx;

/// Compressed adjacency: the neighbours of node `i` are `targets[offsets[i]..offsets[i + 1]]`.
#[derive(Debug, Clone, Default)]
pub(crate) struct Csr {
    offsets: Vec<u32>,
    targets: Vec<NodeIx>,
}

impl Csr {
    /// Builds from `(node, neighbour)` pairs over `n` nodes, dropping repeats and listing each node's neighbours by
    /// `rank`.
    pub(crate) fn from_pairs(n: usize, mut pairs: Vec<(u32, u32)>, rank: &[u32]) -> Self {
        let r = |i: u32| rank.get(i as usize).copied().unwrap_or(u32::MAX);
        pairs.sort_unstable_by_key(|&(a, b)| (a, r(b)));
        pairs.dedup();
        let mut offsets = vec![0u32; n + 1];
        for &(a, _) in &pairs {
            if let Some(o) = offsets.get_mut(a as usize + 1) {
                *o += 1;
            }
        }
        for i in 1..offsets.len() {
            let prev = offsets.get(i - 1).copied().unwrap_or(0);
            if let Some(o) = offsets.get_mut(i) {
                *o += prev;
            }
        }
        Self { offsets, targets: pairs.into_iter().map(|(_, b)| NodeIx(b)).collect() }
    }

    pub(crate) fn of(&self, i: usize) -> &[NodeIx] {
        let (Some(&start), Some(&end)) = (self.offsets.get(i), self.offsets.get(i + 1)) else { return &[] };
        self.targets.get(start as usize..end as usize).unwrap_or(&[])
    }
}

/// Kahn's algorithm, always taking the ready node of lowest rank: the lexicographically smallest topological order.
/// Returns the order, which is shorter than `n` when some nodes lie on or behind a cycle.
pub(crate) fn kahn(n: usize, prerequisites: &Csr, dependents: &Csr, rank: &[u32], by_rank: &[u32]) -> Vec<NodeIx> {
    let mut indegree: Vec<u32> = (0..n).map(|i| u32::try_from(prerequisites.of(i).len()).unwrap_or(u32::MAX)).collect();
    let mut heap: BinaryHeap<Reverse<u32>> =
        (0..n).filter(|&i| indegree.get(i) == Some(&0)).filter_map(|i| rank.get(i).copied()).map(Reverse).collect();
    let mut order = Vec::with_capacity(n);
    while let Some(Reverse(r)) = heap.pop() {
        let Some(&i) = by_rank.get(r as usize) else { continue };
        order.push(NodeIx(i));
        for d in dependents.of(i as usize) {
            if let Some(deg) = indegree.get_mut(d.u()) {
                *deg -= 1;
                if *deg == 0 {
                    if let Some(&rd) = rank.get(d.u()) {
                        heap.push(Reverse(rd));
                    }
                }
            }
        }
    }
    order
}

/// Strongly connected components of the subgraph induced by `members` (Kosaraju, iterative). Only components that
/// form a cycle are returned: two or more nodes, or one node with an edge to itself (`self_loop`).
pub(crate) fn cyclic_components(
    members: &[bool],
    forward: &Csr,
    backward: &Csr,
    self_loop: &[bool],
) -> Vec<Vec<NodeIx>> {
    let n = members.len();
    let inside = |i: usize| members.get(i).copied().unwrap_or(false);

    // Pass 1: finish order of a depth-first search over `forward`.
    let mut visited = vec![false; n];
    let mut finished: Vec<usize> = Vec::new();
    let mut stack: Vec<(usize, usize)> = Vec::new();
    for root in 0..n {
        if !inside(root) || visited.get(root).copied().unwrap_or(true) {
            continue;
        }
        mark(&mut visited, root);
        stack.push((root, 0));
        while let Some(top) = stack.last_mut() {
            let (node, next) = *top;
            match forward.of(node).get(next) {
                Some(child) => {
                    top.1 += 1;
                    let c = child.u();
                    if inside(c) && !visited.get(c).copied().unwrap_or(true) {
                        mark(&mut visited, c);
                        stack.push((c, 0));
                    }
                }
                None => {
                    finished.push(node);
                    stack.pop();
                }
            }
        }
    }

    // Pass 2: in reverse finish order, everything reachable over `backward` is one component.
    let mut assigned = vec![false; n];
    let mut components = Vec::new();
    let mut frontier: Vec<usize> = Vec::new();
    for &root in finished.iter().rev() {
        if assigned.get(root).copied().unwrap_or(true) {
            continue;
        }
        mark(&mut assigned, root);
        let mut component = vec![NodeIx(root as u32)];
        frontier.push(root);
        while let Some(node) = frontier.pop() {
            for p in backward.of(node) {
                let i = p.u();
                if inside(i) && !assigned.get(i).copied().unwrap_or(true) {
                    mark(&mut assigned, i);
                    component.push(*p);
                    frontier.push(i);
                }
            }
        }
        let cyclic = component.len() > 1 || self_loop.get(root).copied().unwrap_or(false);
        if cyclic {
            components.push(component);
        }
    }
    components
}

fn mark(flags: &mut [bool], i: usize) {
    if let Some(f) = flags.get_mut(i) {
        *f = true;
    }
}

/// One shortest closed path through `start` that stays inside `component`, following `forward` edges. The path
/// lists `start` first and does not repeat it at the end.
pub(crate) fn shortest_cycle(start: NodeIx, component: &[bool], forward: &Csr) -> Vec<NodeIx> {
    let n = component.len();
    let mut parent: Vec<u32> = vec![u32::MAX; n];
    let mut queue = alloc::collections::VecDeque::new();
    queue.push_back(start.u());
    let mut seen = vec![false; n];
    mark(&mut seen, start.u());
    while let Some(node) = queue.pop_front() {
        for next in forward.of(node) {
            let i = next.u();
            if i == start.u() {
                let mut path = vec![NodeIx(node as u32)];
                let mut at = node;
                while at != start.u() {
                    let Some(&p) = parent.get(at) else { break };
                    if p == u32::MAX {
                        break;
                    }
                    path.push(NodeIx(p));
                    at = p as usize;
                }
                path.reverse();
                return path;
            }
            if component.get(i).copied().unwrap_or(false) && !seen.get(i).copied().unwrap_or(true) {
                mark(&mut seen, i);
                if let Some(slot) = parent.get_mut(i) {
                    *slot = node as u32;
                }
                queue.push_back(i);
            }
        }
    }
    vec![start]
}

//! # michi-graph
//!
//! Deterministic dependency graphs for dev tools: steps in a pipeline, operations in a release, packages in a
//! workspace, tasks in a plan.
//!
//! 1. Declare nodes and edges with a [`GraphBuilder`]. An edge says a dependent depends on a prerequisite, and has a
//!    kind (`()` unless you need kinds). Building never fails: problems are recorded for validation.
//! 2. [`Graph::validate`] (every edge) or [`Graph::validate_filtered`] (edges you choose) returns a [`Dag`], or
//!    [`Violations`] listing every problem at once: duplicate nodes, unknown dependencies, self-dependencies and
//!    cycles, each cycle with one concrete loop.
//! 3. Query the [`Dag`]: topological order, layers, ready sets, ancestors and descendants.
//!
//! The caller picks how ties break ([`Order::Declaration`] or [`Order::Key`]) and every output follows it, so the same
//! input always gives the same result. Nothing recurses, so long chains cannot overflow the stack.
//!
//! ```
//! use michi_graph::{Dag, Order};
//!
//! let dag = Dag::from_nodes(
//!     [("build", vec![]), ("test", vec!["build"]), ("lint", vec![]), ("ship", vec!["test", "lint"])],
//!     Order::Declaration,
//! )
//! .unwrap();
//! assert_eq!(dag.keys_in_order().copied().collect::<Vec<_>>(), ["build", "test", "lint", "ship"]);
//!
//! let layers: Vec<Vec<&str>> = dag.layers().iter().map(|l| l.iter().map(|&ix| *dag.key(ix).unwrap()).collect()).collect();
//! assert_eq!(layers, [vec!["build", "lint"], vec!["test"], vec!["ship"]]);
//!
//! let err = Dag::from_nodes([("a", vec!["b"]), ("b", vec!["a"])], Order::Key).unwrap_err();
//! assert_eq!(err.to_string(), "dependency cycle: a depends on b, which depends on a");
//! ```
//!
//! See `docs/spec/09-graph.md` in the michi repository.

#![no_std]
#![forbid(unsafe_code)]
#![warn(missing_docs)]
#![warn(clippy::unwrap_used, clippy::expect_used, clippy::indexing_slicing)]
#![warn(clippy::must_use_candidate, clippy::missing_errors_doc, clippy::missing_panics_doc)]
#![warn(missing_debug_implementations)]

extern crate alloc;

// Runs the README examples as doctests without making them the rendered crate docs.
#[cfg(doctest)]
#[doc = include_str!("../README.md")]
struct ReadmeDoctests;

mod algo;
mod builder;
mod dag;
mod graph;
mod violation;

pub use builder::{Decl, GraphBuilder};
pub use dag::{Dag, Layers};
pub use graph::{Dangling, EdgeRef, Graph};
pub use violation::{Cycle, Violation, Violations};

/// A node's declaration position in its graph: the first node declared is 0.
///
/// There is no public constructor. Methods that take a `NodeIx` return an empty slice or `None` for an index their
/// graph does not have, so an index from another graph never panics.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct NodeIx(u32);

impl NodeIx {
    /// The declaration position as a `usize`, for indexing your own per-node storage.
    #[must_use]
    pub fn index(self) -> usize {
        self.0 as usize
    }

    fn u(self) -> usize {
        self.0 as usize
    }
}

/// How ties break wherever order is free: in the topological order, layers, ready sets, closures and cycle reports.
#[non_exhaustive]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Order {
    /// The earliest-declared node first: things run in the order they were written.
    #[default]
    Declaration,
    /// The smallest key first: shuffling the declarations changes nothing.
    Key,
}

/// What validation does with an edge whose prerequisite no node has. The edge is kept in [`Graph::dangling`] either
/// way.
#[non_exhaustive]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum UnknownTargets {
    /// Report it as [`Violation::UnknownDependency`].
    #[default]
    Error,
    /// Leave it out of the dag without a violation, for prerequisites that live outside the graph on purpose.
    Ignore,
}

