  9	/// A node declaration, returned by [`GraphBuilder::node`]. Edges hang off the declaration rather than the key, so the
 10	/// edges of a duplicate declaration are dropped with it instead of landing on the first node with that key.
 11	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 12	pub struct Decl(u32);
 13	
 14	/// Collects nodes and edges. [`GraphBuilder::build`] never fails; problems are reported when the graph is validated.
 15	#[derive(Debug, Clone)]
 16	pub struct GraphBuilder<K, E = ()> {
 17	    decls: Vec<K>,
 18	    edges: Vec<(u32, K, E)>,
 19	    overflow: bool,
 20	}
 21	
 22	impl<K: Ord + Clone, E: Ord> Default for GraphBuilder<K, E> {
 23	    fn default() -> Self {
 24	        Self::new()
 25	    }
 26	}
 27	
 28	impl<K: Ord + Clone, E: Ord> GraphBuilder<K, E> {
 29	    /// An empty builder.
 30	    #[must_use]
 31	    pub fn new() -> Self {
 32	        Self { decls: Vec::new(), edges: Vec::new(), overflow: false }
 33	    }
 34	
 35	    /// An empty builder with room for `nodes` declarations.
 36	    #[must_use]
 37	    pub fn with_capacity(nodes: usize) -> Self {
 38	        Self { decls: Vec::with_capacity(nodes), edges: Vec::with_capacity(nodes), overflow: false }
 39	    }
 40	
 41	    /// Declares a node. A later declaration reusing a key is reported as [`crate::Violation::DuplicateNode`], and the
 42	    /// edges added to it are dropped.
 43	    pub fn node(&mut self, key: K) -> Decl {
 44	        match u32::try_from(self.decls.len()) {
 45	            Ok(n) if n < u32::MAX => {
 46	                self.decls.push(key);
 47	                Decl(n)
 48	            }
 49	            _ => {
 50	                self.overflow = true;
 51	                Decl(u32::MAX)
 52	            }
 53	        }
 54	    }
 55	
 56	    /// Adds an edge: `dependent` depends on the node keyed `prerequisite`, which may be declared before or after it.
 57	    /// Repeating an edge with the same kind has no further effect.
 58	    pub fn depends_on(&mut self, dependent: Decl, prerequisite: K, kind: E) -> &mut Self {
 59	        if (dependent.0 as usize) < self.decls.len() {
 60	            self.edges.push((dependent.0, prerequisite, kind));
 61	        }
 62	        self
 63	    }
 64	
 65	    /// Builds the graph, keeping every node and edge it can use and recording the rest: duplicate declarations,
 66	    /// edges to unknown keys (always kept in [`Graph::dangling`]; `unknown` decides whether validation reports them)
 67	    /// and more than `u32::MAX - 1` nodes.
 68	    #[must_use]
 69	    pub fn build(self, unknown: UnknownTargets) -> Graph<K, E> {
 70	        let Self { decls, edges, overflow } = self;
 71	
 72	        // Declarations sorted by key, ties by position: the first of each run of equal keys is the node.
 73	        let mut sorted: Vec<u32> = (0..decls.len()).filter_map(|i| u32::try_from(i).ok()).collect();
 74	        sorted.sort_by(|&a, &b| decl(&decls, a).cmp(&decl(&decls, b)).then(a.cmp(&b)));
 75	        let mut is_duplicate = alloc::vec![false; decls.len()];
 76	        for pair in sorted.windows(2) {
 77	            if let [a, b] = *pair {
 78	                if decl(&decls, a) == decl(&decls, b) {
 79	                    if let Some(d) = is_duplicate.get_mut(b as usize) {
 80	                        *d = true;
 81	                    }
 82	                }
 83	            }
 84	        }
 85	
 86	        let mut node_of_decl: Vec<Option<u32>> = Vec::with_capacity(decls.len());
 87	        let mut keys: Vec<K> = Vec::with_capacity(decls.len());
 88	        let mut duplicates: Vec<K> = Vec::new();
 89	        for (key, dup) in decls.into_iter().zip(is_duplicate) {
 90	            if dup {
 91	                node_of_decl.push(None);
 92	                duplicates.push(key);
 93	            } else {
 94	                node_of_decl.push(u32::try_from(keys.len()).ok());
 95	                keys.push(key);
 96	            }
 97	        }
 98	        let mut by_key: Vec<u32> = (0..keys.len()).filter_map(|i| u32::try_from(i).ok()).collect();
 99	        by_key.sort_by(|&a, &b| decl(&keys, a).cmp(&decl(&keys, b)));
100	
101	        let mut resolved: Vec<Edge<E>> = Vec::with_capacity(edges.len());
102	        let mut dangling: Vec<Dangling<K, E>> = Vec::new();
103	        for (seq, (d, prerequisite, kind)) in edges.into_iter().enumerate() {
104	            let Some(dependent) = node_of_decl.get(d as usize).copied().flatten() else { continue };
105	            match lookup(&keys, &by_key, &prerequisite) {
106	                Some(p) => resolved.push(Edge { dependent, prerequisite: p, kind, seq }),
107	                None => dangling.push(Dangling { dependent: NodeIx(dependent), prerequisite, kind, seq }),
108	            }
109	        }
110	        // One edge per (dependent, prerequisite, kind), the first declared; then back to declaration order.
111	        resolved.sort_by(|a, b| {
112	            (a.dependent, a.prerequisite, &a.kind, a.seq).cmp(&(b.dependent, b.prerequisite, &b.kind, b.seq))
113	        });
114	        resolved.dedup_by(|b, a| a.dependent == b.dependent && a.prerequisite == b.prerequisite && a.kind == b.kind);
115	        resolved.sort_by_key(|e| e.seq);
116	        dangling.sort_by(|a, b| {
117	            (a.dependent, &a.prerequisite, &a.kind, a.seq).cmp(&(b.dependent, &b.prerequisite, &b.kind, b.seq))
118	        });
119	        dangling.dedup_by(|b, a| a.dependent == b.dependent && a.prerequisite == b.prerequisite && a.kind == b.kind);
120	        dangling.sort_by_key(|e| e.seq);
121	
122	        Graph {
123	            keys: Arc::from(keys),
124	            by_key: Arc::from(by_key),
125	            edges: resolved,
126	            dangling,
127	            duplicates,
128	            unknown,
129	            overflow,
130	        }
131	    }
132	}
133	
134	fn decl<K>(keys: &[K], i: u32) -> Option<&K> {
135	    keys.get(i as usize)
136	}
137	
138	/// Binary search of `by_key` (node indices sorted by key) for `key`.
139	pub(crate) fn lookup<K, Q>(keys: &[K], by_key: &[u32], key: &Q) -> Option<u32>
140	where
141	    K: core::borrow::Borrow<Q>,
142	    Q: Ord + ?Sized,
143	{
144	    let pos = by_key
145	        .binary_search_by(|&i| match keys.get(i as usize) {
146	            Some(k) => k.borrow().cmp(key),
147	            None => core::cmp::Ordering::Less,
148	        })
149	        .ok()?;
150	    by_key.get(pos).copied()
151	}

  1	//! Index-level algorithms: adjacency, Kahn, Kosaraju and shortest cycles. Nothing here recurses.
  2	
  3	use alloc::collections::BinaryHeap;
  4	use alloc::vec;
  5	use alloc::vec::Vec;
  6	use core::cmp::Reverse;
  7	
  8	use crate::NodeIx;
  9	
 10	/// Compressed adjacency: the neighbours of node `i` are `targets[offsets[i]..offsets[i + 1]]`.
 11	#[derive(Debug, Clone, Default)]
 12	pub(crate) struct Csr {
 13	    offsets: Vec<u32>,
 14	    targets: Vec<NodeIx>,
 15	}
 16	
 17	impl Csr {
 18	    /// Builds from `(node, neighbour)` pairs over `n` nodes, dropping repeats and listing each node's neighbours by
 19	    /// `rank`.
 20	    pub(crate) fn from_pairs(n: usize, mut pairs: Vec<(u32, u32)>, rank: &[u32]) -> Self {
 21	        let r = |i: u32| rank.get(i as usize).copied().unwrap_or(u32::MAX);
 22	        pairs.sort_unstable_by_key(|&(a, b)| (a, r(b)));
 23	        pairs.dedup();
 24	        let mut offsets = vec![0u32; n + 1];
 25	        for &(a, _) in &pairs {
 26	            if let Some(o) = offsets.get_mut(a as usize + 1) {
 27	                *o += 1;
 28	            }
 29	        }
 30	        for i in 1..offsets.len() {
 31	            let prev = offsets.get(i - 1).copied().unwrap_or(0);
 32	            if let Some(o) = offsets.get_mut(i) {
 33	                *o += prev;
 34	            }
 35	        }
 36	        Self { offsets, targets: pairs.into_iter().map(|(_, b)| NodeIx(b)).collect() }
 37	    }
 38	
 39	    pub(crate) fn of(&self, i: usize) -> &[NodeIx] {
 40	        let (Some(&start), Some(&end)) = (self.offsets.get(i), self.offsets.get(i + 1)) else { return &[] };
 41	        self.targets.get(start as usize..end as usize).unwrap_or(&[])
 42	    }
 43	}
 44	
 45	/// Kahn's algorithm, always taking the ready node of lowest rank: the lexicographically smallest topological order.
 46	/// Returns the order, which is shorter than `n` when some nodes lie on or behind a cycle.
 47	pub(crate) fn kahn(n: usize, prerequisites: &Csr, dependents: &Csr, rank: &[u32], by_rank: &[u32]) -> Vec<NodeIx> {
 48	    let mut indegree: Vec<u32> = (0..n).map(|i| u32::try_from(prerequisites.of(i).len()).unwrap_or(u32::MAX)).collect();
 49	    let mut heap: BinaryHeap<Reverse<u32>> =
 50	        (0..n).filter(|&i| indegree.get(i) == Some(&0)).filter_map(|i| rank.get(i).copied()).map(Reverse).collect();
 51	    let mut order = Vec::with_capacity(n);
 52	    while let Some(Reverse(r)) = heap.pop() {
 53	        let Some(&i) = by_rank.get(r as usize) else { continue };
 54	        order.push(NodeIx(i));
 55	        for d in dependents.of(i as usize) {
 56	            if let Some(deg) = indegree.get_mut(d.u()) {
 57	                *deg -= 1;
 58	                if *deg == 0 {
 59	                    if let Some(&rd) = rank.get(d.u()) {
 60	                        heap.push(Reverse(rd));
 61	                    }
 62	                }
 63	            }
 64	        }
 65	    }
 66	    order
 67	}
 68	
 69	/// Strongly connected components of the subgraph induced by `members` (Kosaraju, iterative). Only components that
 70	/// form a cycle are returned: two or more nodes, or one node with an edge to itself (`self_loop`).
 71	pub(crate) fn cyclic_components(
 72	    members: &[bool],
 73	    forward: &Csr,
 74	    backward: &Csr,
 75	    self_loop: &[bool],
 76	) -> Vec<Vec<NodeIx>> {
 77	    let n = members.len();
 78	    let inside = |i: usize| members.get(i).copied().unwrap_or(false);
 79	
 80	    // Pass 1: finish order of a depth-first search over `forward`.
 81	    let mut visited = vec![false; n];
 82	    let mut finished: Vec<usize> = Vec::new();
 83	    let mut stack: Vec<(usize, usize)> = Vec::new();
 84	    for root in 0..n {
 85	        if !inside(root) || visited.get(root).copied().unwrap_or(true) {
 86	            continue;
 87	        }
 88	        mark(&mut visited, root);
 89	        stack.push((root, 0));
 90	        while let Some(top) = stack.last_mut() {
 91	            let (node, next) = *top;
 92	            match forward.of(node).get(next) {
 93	                Some(child) => {
 94	                    top.1 += 1;
 95	                    let c = child.u();
 96	                    if inside(c) && !visited.get(c).copied().unwrap_or(true) {
 97	                        mark(&mut visited, c);
 98	                        stack.push((c, 0));
 99	                    }
100	                }
101	                None => {
102	                    finished.push(node);
103	                    stack.pop();
104	                }
105	            }
106	        }
107	    }
108	
109	    // Pass 2: in reverse finish order, everything reachable over `backward` is one component.
110	    let mut assigned = vec![false; n];
111	    let mut components = Vec::new();
112	    let mut frontier: Vec<usize> = Vec::new();
113	    for &root in finished.iter().rev() {
114	        if assigned.get(root).copied().unwrap_or(true) {
115	            continue;
116	        }
117	        mark(&mut assigned, root);
118	        let mut component = vec![NodeIx(root as u32)];
119	        frontier.push(root);
120	        while let Some(node) = frontier.pop() {
121	            for p in backward.of(node) {
122	                let i = p.u();
123	                if inside(i) && !assigned.get(i).copied().unwrap_or(true) {
124	                    mark(&mut assigned, i);
125	                    component.push(*p);
126	                    frontier.push(i);
127	                }
128	            }
129	        }
130	        let cyclic = component.len() > 1 || self_loop.get(root).copied().unwrap_or(false);
131	        if cyclic {
132	            components.push(component);
133	        }
134	    }
135	    components
136	}
137	
138	fn mark(flags: &mut [bool], i: usize) {
139	    if let Some(f) = flags.get_mut(i) {
140	        *f = true;
141	    }
142	}
143	
144	/// One shortest closed path through `start` that stays inside `component`, following `forward` edges. The path
145	/// lists `start` first and does not repeat it at the end.
146	pub(crate) fn shortest_cycle(start: NodeIx, component: &[bool], forward: &Csr) -> Vec<NodeIx> {
147	    let n = component.len();
148	    let mut parent: Vec<u32> = vec![u32::MAX; n];
149	    let mut queue = alloc::collections::VecDeque::new();
150	    queue.push_back(start.u());
151	    let mut seen = vec![false; n];
152	    mark(&mut seen, start.u());
153	    while let Some(node) = queue.pop_front() {
154	        for next in forward.of(node) {
155	            let i = next.u();
156	            if i == start.u() {
157	                let mut path = vec![NodeIx(node as u32)];
158	                let mut at = node;
159	                while at != start.u() {
160	                    let Some(&p) = parent.get(at) else { break };
161	                    if p == u32::MAX {
162	                        break;
163	                    }
164	                    path.push(NodeIx(p));
165	                    at = p as usize;
166	                }
167	                path.reverse();
168	                return path;
169	            }
170	            if component.get(i).copied().unwrap_or(false) && !seen.get(i).copied().unwrap_or(true) {
171	                mark(&mut seen, i);
172	                if let Some(slot) = parent.get_mut(i) {
173	                    *slot = node as u32;
174	                }
175	                queue.push_back(i);
176	            }
177	        }
178	    }
179	    vec![start]
180	}

