243	/// A random graph over `n` nodes: each node lists prerequisite indices (possibly itself or repeats).
244	fn graphs() -> impl Strategy<Value = Vec<Vec<usize>>> {
245	    (1usize..14).prop_flat_map(|n| proptest::collection::vec(proptest::collection::vec(0..n, 0..4), n))
246	}
