248	/// `reach[i][j]`: j is reachable from i by following prerequisites (one or more steps).
249	fn reachability(adj: &[Vec<usize>]) -> Vec<Vec<bool>> {
250	    let n = adj.len();
251	    let mut reach = vec![vec![false; n]; n];
252	    for (i, deps) in adj.iter().enumerate() {
253	        for &j in deps {
254	            reach[i][j] = true;
255	        }
256	    }
257	    for k in 0..n {
258	        for i in 0..n {
259	            if reach[i][k] {
260	                for j in 0..n {
261	                    if reach[k][j] {
262	                        reach[i][j] = true;
263	                    }
264	                }
265	            }
266	        }
267	    }
268	    reach
269	}
