271	fn build(adj: &[Vec<usize>], names: &[u32]) -> michi_graph::Graph<u32> {
272	    let mut b = GraphBuilder::<u32>::new();
273	    let decls: Vec<_> = names.iter().map(|&k| b.node(k)).collect();
274	    for (d, deps) in decls.iter().zip(adj) {
275	        for &p in deps {
276	            b.depends_on(*d, names[p], ());
277	        }
278	    }
279	    b.build(UnknownTargets::Error)
280	}
