282	proptest! {
283	    #[test]
284	    fn validation_matches_the_oracle(adj in graphs(), order_is_key in any::<bool>(), seed in any::<u64>()) {
285	        let n = adj.len();
286	        // Keys are a shuffled permutation, so key order differs from declaration order.
287	        let mut names: Vec<u32> = (0..n as u32).collect();
288	        let mut s = seed | 1;
289	        for i in (1..n).rev() {
290	            s ^= s << 13; s ^= s >> 7; s ^= s << 17;
291	            names.swap(i, (s % (i as u64 + 1)) as usize);
292	        }
293	        let order = if order_is_key { Order::Key } else { Order::Declaration };
294	        let rank = |i: usize| if order_is_key { names[i] as usize } else { i };
295	        let reach = reachability(&adj);
296	        let self_dep: BTreeSet<usize> = (0..n).filter(|&i| adj[i].contains(&i)).collect();
297	        // Without self-edges: strongly connected components of size > 1.
298	        let no_self: Vec<Vec<usize>> = adj.iter().enumerate().map(|(i, d)| d.iter().copied().filter(|&p| p != i).collect()).collect();
299	        let r2 = reachability(&no_self);
300	        let mut expected_cycles: BTreeSet<Vec<u32>> = BTreeSet::new();
301	        for i in 0..n {
302	            let mut comp: Vec<usize> = (0..n).filter(|&j| j == i || (r2[i][j] && r2[j][i])).collect();
303	            if comp.len() > 1 {
304	                comp.sort_by_key(|&j| rank(j));
305	                expected_cycles.insert(comp.iter().map(|&j| names[j]).collect());
306	            }
307	        }
308	
309	        match build(&adj, &names).validate(order) {
310	            Ok(dag) => {
311	                prop_assert!(self_dep.is_empty() && expected_cycles.is_empty());
312	                let _ = reach;
313	                // Topological validity and lexicographic minimality under the rank.
314	                let pos: Vec<usize> = { let mut p = vec![0; n]; for (k, ix) in dag.order().iter().enumerate() { p[ix.index()] = k; } p };
315	                for (i, deps) in adj.iter().enumerate() { for &p in deps { prop_assert!(pos[p] < pos[i]); } }
316	                let mut placed = vec![false; n];
317	                for ix in dag.order() {
318	                    let best = (0..n).filter(|&j| !placed[j] && adj[j].iter().all(|&p| placed[p])).min_by_key(|&j| rank(j));
319	                    prop_assert_eq!(Some(ix.index()), best);
320	                    placed[ix.index()] = true;
321	                }
322	                // Layers: layer(n) = 1 + max(layer(p)).
323	                let mut layer = vec![0usize; n];
324	                for (li, l) in dag.layers().iter().enumerate() { for ix in l { layer[ix.index()] = li; } }
325	                for i in 0..n {
326	                    let want = adj[i].iter().map(|&p| layer[p] + 1).max().unwrap_or(0);
327	                    prop_assert_eq!(layer[i], want);
328	                }
329	                // Descendants match reachability.
330	                for i in 0..n {
331	                    let got: BTreeSet<usize> = dag.descendants(&[ix_of(&dag, names[i])]).iter().map(|ix| ix.index()).collect();
332	                    let want: BTreeSet<usize> = (0..n).filter(|&j| reach[j][i]).collect();
333	                    prop_assert_eq!(got, want);
334	                }
335	            }
336	            Err(v) => {
337	                let got_self: BTreeSet<u32> = v.iter().filter_map(|x| match x { Violation::SelfDependency { key } => Some(*key), _ => None }).collect();
338	                prop_assert_eq!(got_self, self_dep.iter().map(|&i| names[i]).collect::<BTreeSet<_>>());
339	                let got_cycles: BTreeSet<Vec<u32>> = v.iter().filter_map(|x| match x { Violation::Cycle(c) => Some(c.members().to_vec()), _ => None }).collect();
340	                prop_assert_eq!(&got_cycles, &expected_cycles);
341	                for x in &v {
342	                    if let Violation::Cycle(c) = x {
343	                        // The path is a real loop inside the component, starting at its first member.
344	                        let path = c.path();
345	                        prop_assert_eq!(path.first(), c.members().first());
346	                        let idx = |k: u32| names.iter().position(|&m| m == k).unwrap();
347	                        for w in 0..path.len() {
348	                            let (a, b) = (idx(path[w]), idx(path[(w + 1) % path.len()]));
349	                            prop_assert!(adj[a].contains(&b) && a != b);
350	                        }
351	                    }
352	                }
353	            }
354	        }
355	    }
356	}
