103	    where
104	        K: Borrow<Q>,
105	        Q: Ord + ?Sized,
106	    {
107	        lookup(&self.keys, &self.by_key, key).map(NodeIx)
108	    }
109	
110	    /// Edges whose prerequisite no node has, in declaration order.
111	    #[must_use]
112	    pub fn dangling(&self) -> &[Dangling<K, E>] {
113	        &self.dangling
114	    }
115	
116	    /// Keys declared more than once, one entry per later declaration, in declaration order.
117	    #[must_use]
118	    pub fn duplicates(&self) -> &[K] {
119	        &self.duplicates
120	    }
121	
122	    /// Validates the graph with every edge. See [`Graph::validate_filtered`].
123	    ///
124	    /// # Errors
125	    ///
126	    /// [`Violations`] listing every problem when the graph is not a valid dag.
127	    pub fn validate(&self, order: Order) -> Result<Dag<K>, Violations<K>> {
128	        self.validate_filtered(|_| true, order)
129	    }
130	
131	    /// Validates the graph with the edges `keep` accepts and returns a [`Dag`], or every problem at once, in this
132	    /// order: duplicate nodes, then unknown dependencies (unless ignored) and self-dependencies by the dependent's
133	    /// declaration position and the edge's, then cycles. Cycles made only of rejected edges are not problems.
134	    ///
135	    /// # Errors
136	    ///
137	    /// [`Violations`] listing every problem when the kept edges do not form a valid dag.
138	    pub fn validate_filtered(
139	        &self,
140	        keep: impl FnMut(EdgeRef<'_, K, E>) -> bool,
141	        order: Order,
142	    ) -> Result<Dag<K>, Violations<K>> {
143	        let kept = self.kept(keep, order);
144	        let n = self.len();
145	        let mut violations: Vec<Violation<K>> =
146	            self.duplicates.iter().map(|key| Violation::DuplicateNode { key: key.clone() }).collect();
147	        if self.overflow {
148	            violations.push(Violation::TooManyNodes);
149	        }
150	
151	        // Unknown dependencies and self-dependencies, by dependent then edge declaration order.
152	        let mut edge_problems: Vec<(u32, usize, Violation<K>)> = Vec::new();
153	        if self.unknown == UnknownTargets::Error {
154	            for d in &self.dangling {
155	                if let Some(dependent) = self.key(d.dependent) {
156	                    edge_problems.push((
157	                        d.dependent.0,
158	                        d.seq,
159	                        Violation::UnknownDependency {
160	                            dependent: dependent.clone(),
161	                            prerequisite: d.prerequisite.clone(),
162	                        },
163	                    ));
164	                }
165	            }
166	        }
167	        for (i, seq) in kept.self_loop_seq.iter().enumerate() {
168	            if let (Some(seq), Some(key), Ok(i)) = (seq, self.keys.get(i), u32::try_from(i)) {
169	                edge_problems.push((i, *seq, Violation::SelfDependency { key: key.clone() }));
170	            }
171	        }
172	        edge_problems.sort_by_key(|&(d, seq, _)| (d, seq));
173	        violations.extend(edge_problems.into_iter().map(|(_, _, v)| v));
174	
175	        let topo = kahn(n, &kept.prerequisites, &kept.dependents, &kept.rank, &kept.by_rank);
176	        if topo.len() < n {
177	            let mut left = vec![true; n];
178	            for ix in &topo {
179	                if let Some(l) = left.get_mut(ix.u()) {
180	                    *l = false;
181	                }
182	            }
183	            let no_self = vec![false; n];
184	            for cycle in self.cycles_in(&left, &kept, &no_self) {
185	                violations.push(Violation::Cycle(cycle));
186	            }
187	        }
188	
189	        if !violations.is_empty() {
190	            return Err(Violations::new(violations));
191	        }
192	        Ok(Dag::new(Arc::clone(&self.keys), Arc::clone(&self.by_key), kept, topo))
193	    }
194	
195	    /// The cycles among the edges `keep` accepts, for graphs that may legitimately contain them. Each strongly
196	    /// connected component that forms a cycle is reported once, a node with an edge to itself included.
197	    #[must_use]
