   144	/// One shortest closed path through `start` that stays inside `component`, following `forward` edges. The path
   145	/// lists `start` first and does not repeat it at the end.
   146	pub(crate) fn shortest_cycle(start: NodeIx, component: &[bool], forward: &Csr) -> Vec<NodeIx> {
   147	    let n = component.len();
   148	    let mut parent: Vec<u32> = vec![u32::MAX; n];
   149	    let mut queue = alloc::collections::VecDeque::new();
   150	    queue.push_back(start.u());
   151	    let mut seen = vec![false; n];
   152	    mark(&mut seen, start.u());
   153	    while let Some(node) = queue.pop_front() {
   154	        for next in forward.of(node) {
   155	            let i = next.u();
   156	            if i == start.u() {
   157	                let mut path = vec![NodeIx(node as u32)];
   158	                let mut at = node;
   159	                while at != start.u() {
   160	                    let Some(&p) = parent.get(at) else { break };
   161	                    if p == u32::MAX {
   162	                        break;
   163	                    }
   164	                    path.push(NodeIx(p));
   165	                    at = p as usize;
   166	                }
   167	                path.reverse();
   168	                return path;
   169	            }
   170	            if component.get(i).copied().unwrap_or(false) && !seen.get(i).copied().unwrap_or(true) {
   171	                mark(&mut seen, i);
   172	                if let Some(slot) = parent.get_mut(i) {
   173	                    *slot = node as u32;
   174	                }
   175	                queue.push_back(i);
   176	            }
   177	        }
   178	    }
   179	    vec![start]
   180	}

